import{_ as s,o as t,c as e,a3 as h}from"./chunks/framework.CVt6dz2a.js";const o=JSON.parse('{"title":"学习路径建议","description":"","frontmatter":{},"headers":[],"relativePath":"learning-path.md","filePath":"learning-path.md","lastUpdated":1793881879000}'),p={name:"learning-path.md"};function r(g,a,c,b,i,l){return t(),e("div",null,[...a[0]||(a[0]=[h('<h1 id="学习路径建议" tabindex="-1">学习路径建议 <a class="header-anchor" href="#学习路径建议" aria-label="Permalink to &quot;学习路径建议&quot;">​</a></h1><p>Three.js 的知识点看似庞杂，但只要遵循&quot;<strong>先搭骨架，再长血肉</strong>&quot;的顺序，学习曲线可以非常平滑。本教程把内容组织为 <strong>39 个模块 × 6 个阶段</strong>（其中 ㉛㉜ 为前瞻内容，不计入考核），并给出推荐的学习节奏与自测标准。</p><h2 id="六个阶段分别学什么" tabindex="-1">六个阶段分别学什么 <a class="header-anchor" href="#六个阶段分别学什么" aria-label="Permalink to &quot;六个阶段分别学什么&quot;">​</a></h2><div class="path-legend"><span><b class="path-stage path-stage--base">基础</b> 建立概念，能跑通最小示例</span><span><b class="path-stage path-stage--adv">进阶</b> 理解原理，掌握可调参数</span><span><b class="path-stage path-stage--pra">实战</b> 组合知识，完成小作品</span></div><ul><li><strong>基础入门</strong>：回答&quot;它是什么、什么时候用&quot;，每个概念配一个 20 行左右的最小示例。</li><li><strong>进阶应用</strong>：回答&quot;参数怎么调、底层怎么运作&quot;，引入多个对象之间的协作关系。</li><li><strong>实战案例</strong>：回答&quot;怎么组合起来做东西&quot;，每章产出一个可交互的小案例。</li></ul><h2 id="推荐学习顺序-四周计划" tabindex="-1">推荐学习顺序（四周计划） <a class="header-anchor" href="#推荐学习顺序-四周计划" aria-label="Permalink to &quot;推荐学习顺序（四周计划）&quot;">​</a></h2><p>下表给出建议顺序、依赖关系与检验标准。每天投入 45–60 分钟，约四周可完成全部内容。</p><table tabindex="0"><thead><tr><th>周次</th><th>模块</th><th>为什么是这个顺序</th><th>学完的检验标准</th></tr></thead><tbody><tr><td>第 1 周</td><td>① 认识 → ② 场景 → ③ 相机 → ④ 渲染器</td><td>先打通&quot;场景→相机→渲染器→画面&quot;这条最小管线，这是所有 Three.js 程序的骨架</td><td>不看教程能手写一个旋转立方体页面</td></tr><tr><td>第 2 周</td><td>⑤ 几何体 → ⑥ 材质 → ⑦ 纹理</td><td>解决&quot;画面里放什么、它长什么样&quot;，三者共同决定物体外观</td><td>能为物体贴上自制图案并解释 UV 是什么</td></tr><tr><td>第 3 周</td><td>⑧ 灯光 → ⑨ 动画</td><td>先让静态场景有明暗质感，再让它动起来，符合观察习惯</td><td>能做出带阴影、可循环播放的关键帧动画</td></tr><tr><td>第 4 周</td><td>⑩ 交互 → ⑪ 综合实战</td><td>最后处理用户输入，把前面所有模块组装成完整作品</td><td>完成一个可旋转、可点击的 3D 场景小作品</td></tr></tbody></table><h2 id="精通方向扩展-阶段二-六" tabindex="-1">精通方向扩展（阶段二～六） <a class="header-anchor" href="#精通方向扩展-阶段二-六" aria-label="Permalink to &quot;精通方向扩展（阶段二～六）&quot;">​</a></h2><p>完成阶段一（①–⑪）后，你已经&quot;会用&quot;Three.js。精通方向的扩展模块从 ⑫ 起按阶段持续扩充，目标是把能力提升到<strong>企业级复杂场景</strong>：</p><ul><li><strong>阶段二 · 视觉与资产核心能力（⑫–⑰）</strong>：自定义着色器、后处理管线、高级光照 IBL、glTF 资产管线、大场景优化、粒子与 GPU 计算。学完后能独立实现定制特效、接入真实美术资产、扛起万级实例场景。建议节奏约 <strong>6 周</strong>。</li><li><strong>阶段三 · 工程化体系（⑱–⑳）</strong>：React Three Fiber 集成、工程化与性能体系、测试与质量保障。学完后能按企业工程标准落地 3D 项目。建议节奏约 <strong>3 周</strong>。</li><li><strong>阶段四 · 行业场景实战（㉑–㉓）</strong>：可视化大屏与数字孪生、WebXR、物理仿真与游戏化。学完后能交付行业场景综合作品。建议节奏约 <strong>3 周</strong>。</li><li><strong>阶段五 · 精通闭环（㉔–㉜）</strong>：色彩管理与图形学原理、线上监控与容错、GPU 性能治理、材质着色器进阶与 NPR 风格化、程序化建模、3D 数据可视化，以及 WebGPU/TSL 前瞻。学完后能解释&quot;画面为什么是这样&quot;、在上线环境里自证健康，并具备下一代渲染 API 的迁移能力。</li><li><strong>阶段六 · 行业纵深（㉝–㊳）</strong>：跨端与框架广度、GIS 深度、场景编辑器与配置化平台、数字人、游戏化与交互系统。学完后能承担行业项目的架构与落地。</li></ul><p>节奏建议与阶段一相同：每天投入 <strong>45–60 分钟</strong>，先跑通演示再改参数。每个扩展模块同样按&quot;基础入门 → 进阶应用 → 实战案例&quot;三篇组织，并在开篇用已学模块的旧案例&quot;接桥&quot;过渡。</p><h2 id="完整模块索引" tabindex="-1">完整模块索引 <a class="header-anchor" href="#完整模块索引" aria-label="Permalink to &quot;完整模块索引&quot;">​</a></h2><div class="path-grid"><a class="path-card" href="/guide/01-intro/basics"><h4>① 认识 Three.js</h4><p><b class="path-stage path-stage--base">基础</b>第一个场景<br><b class="path-stage path-stage--adv">进阶</b>工程化与调试<br><b class="path-stage path-stage--pra">实战</b>开发模板</p></a><a class="path-card" href="/guide/02-scene/basics"><h4>② 场景 Scene</h4><p><b class="path-stage path-stage--base">基础</b>场景图与坐标<br><b class="path-stage path-stage--adv">进阶</b>层级矩阵与雾<br><b class="path-stage path-stage--pra">实战</b>太阳系模型</p></a><a class="path-card" href="/guide/03-camera/basics"><h4>③ 相机 Camera</h4><p><b class="path-stage path-stage--base">基础</b>透视相机<br><b class="path-stage path-stage--adv">进阶</b>正交与控制器<br><b class="path-stage path-stage--pra">实战</b>四视口观察器</p></a><a class="path-card" href="/guide/04-renderer/basics"><h4>④ 渲染器 Renderer</h4><p><b class="path-stage path-stage--base">基础</b>渲染循环<br><b class="path-stage path-stage--adv">进阶</b>画质与色调映射<br><b class="path-stage path-stage--pra">实战</b>帧率自适应</p></a><a class="path-card" href="/guide/05-geometry/basics"><h4>⑤ 几何体 Geometry</h4><p><b class="path-stage path-stage--base">基础</b>内置几何体<br><b class="path-stage path-stage--adv">进阶</b>自定义顶点属性<br><b class="path-stage path-stage--pra">实战</b>顶点形变动画</p></a><a class="path-card" href="/guide/06-material/basics"><h4>⑥ 材质 Material</h4><p><b class="path-stage path-stage--base">基础</b>四种材质对比<br><b class="path-stage path-stage--adv">进阶</b>物理材质与环境<br><b class="path-stage path-stage--pra">实战</b>材质实验室</p></a><a class="path-card" href="/guide/07-texture/basics"><h4>⑦ 纹理 Texture</h4><p><b class="path-stage path-stage--base">基础</b>UV 与程序化纹理<br><b class="path-stage path-stage--adv">进阶</b>过滤与环绕<br><b class="path-stage path-stage--pra">实战</b>流动纹理</p></a><a class="path-card" href="/guide/08-light/basics"><h4>⑧ 灯光 Light</h4><p><b class="path-stage path-stage--base">基础</b>五种光源<br><b class="path-stage path-stage--adv">进阶</b>阴影映射调优<br><b class="path-stage path-stage--pra">实战</b>三点布光</p></a><a class="path-card" href="/guide/09-animation/basics"><h4>⑨ 动画 Animation</h4><p><b class="path-stage path-stage--base">基础</b>循环与缓动<br><b class="path-stage path-stage--adv">进阶</b>关键帧混合器<br><b class="path-stage path-stage--pra">实战</b>时间轴播放器</p></a><a class="path-card" href="/guide/10-interaction/basics"><h4>⑩ 交互 Interaction</h4><p><b class="path-stage path-stage--base">基础</b>Raycaster 拾取<br><b class="path-stage path-stage--adv">进阶</b>控制器与拖拽<br><b class="path-stage path-stage--pra">实战</b>3D 产品展厅</p></a><a class="path-card" href="/guide/11-capstone/basics"><h4>⑪ 综合实战</h4><p><b class="path-stage path-stage--base">基础</b>架构设计<br><b class="path-stage path-stage--adv">进阶</b>核心实现<br><b class="path-stage path-stage--pra">实战</b>扩展与优化练习</p></a><a class="path-card" href="/guide/12-shader/basics"><h4>⑫ 自定义着色器 GLSL</h4><p><b class="path-stage path-stage--adv">精通</b>GLSL 语法、Uniforms 传参、扫描线与全息特效</p></a><a class="path-card" href="/guide/13-postprocessing/basics"><h4>⑬ 后处理管线</h4><p><b class="path-stage path-stage--adv">精通</b>RenderTarget、EffectComposer、Bloom 与自定义 Pass</p></a><a class="path-card" href="/guide/14-lighting-ibl/basics"><h4>⑭ 高级光照与 IBL</h4><p><b class="path-stage path-stage--adv">精通</b>HDR 环境贴图、光照探针、高保真产品渲染</p></a><a class="path-card" href="/guide/15-gltf-pipeline/basics"><h4>⑮ glTF 资产管线</h4><p><b class="path-stage path-stage--adv">精通</b>GLTFLoader、DRACO/KTX2 压缩、资产交付流水线与骨骼动画</p></a><a class="path-card" href="/guide/16-large-scene/basics"><h4>⑯ 大场景组织与优化</h4><p><b class="path-stage path-stage--adv">精通</b>性能读数、Instancing、LOD 与 three-mesh-bvh</p></a><a class="path-card" href="/guide/17-particles-gpgpu/basics"><h4>⑰ 粒子与 GPU 计算</h4><p><b class="path-stage path-stage--adv">精通</b>Points 粒子、FBO 离屏计算、GPGPU 粒子</p></a><a class="path-card" href="/guide/18-react-three-fiber/basics"><h4>⑱ React Three Fiber</h4><p><b class="path-stage path-stage--adv">精通</b>声明式 3D、useFrame、状态管理与 drei 生态</p></a><a class="path-card" href="/guide/19-engineering-performance/basics"><h4>⑲ 工程化与性能体系</h4><p><b class="path-stage path-stage--adv">精通</b>性能预算、资源释放、Worker、画质分级与灰度监控</p></a><a class="path-card" href="/guide/20-testing-quality/basics"><h4>⑳ 测试与质量保障</h4><p><b class="path-stage path-stage--adv">精通</b>可测性设计、视觉回归、性能与体积断言、CI 门禁</p></a><a class="path-card" href="/guide/21-digital-twin/basics"><h4>㉑ 大屏与数字孪生</h4><p><b class="path-stage path-stage--adv">精通</b>大屏 3D 架构、相机漫游、标注与 GIS</p></a><a class="path-card" href="/guide/22-webxr/basics"><h4>㉒ WebXR 沉浸式体验</h4><p><b class="path-stage path-stage--adv">精通</b>VR/AR 会话、手柄交互、AR 产品放置</p></a><a class="path-card" href="/guide/23-physics/basics"><h4>㉓ 物理仿真与游戏化</h4><p><b class="path-stage path-stage--adv">精通</b>物理引擎、刚体碰撞、角色控制器与小游戏</p></a><a class="path-card" href="/guide/24-color-graphics/basics"><h4>㉔ 色彩管理与图形学原理</h4><p><b class="path-stage path-stage--adv">精通</b>线性工作流、HDR 精度、色带与跨设备校准</p></a><a class="path-card" href="/guide/25-monitoring-resilience/basics"><h4>㉕ 线上监控与容错</h4><p><b class="path-stage path-stage--adv">精通</b>上下文丢失自愈、降级阶梯、监控上报体系</p></a><a class="path-card" href="/guide/26-gpu-profiling/basics"><h4>㉖ 性能治理深水区</h4><p><b class="path-stage path-stage--adv">精通</b>CPU/GPU 帧时间、Overdraw、带宽与显存账本</p></a><a class="path-card" href="/guide/27-material-shader-advanced/basics"><h4>㉗ 材质与着色器扩展技法</h4><p><b class="path-stage path-stage--adv">精通</b>onBeforeCompile、自定义 PBR、材质预设库</p></a><a class="path-card" href="/guide/28-npr-stylized/basics"><h4>㉘ NPR 风格化渲染</h4><p><b class="path-stage path-stage--adv">精通</b>四种描边、卡通色阶、水墨与漫画管线</p></a><a class="path-card" href="/guide/29-procedural-modeling/basics"><h4>㉙ 程序化建模</h4><p><b class="path-stage path-stage--adv">精通</b>噪声几何、L-System 生长、程序化城市</p></a><a class="path-card" href="/guide/30-data-visualization-3d/basics"><h4>㉚ 3D 数据可视化</h4><p><b class="path-stage path-stage--adv">精通</b>图表语法、十万级散点、可交互看板</p></a><a class="path-card" href="/guide/31-webgpu/basics"><h4>㉛ WebGPU 入门</h4><p><b class="path-stage path-stage--adv">前瞻</b>能力探测、WebGPURenderer、WGSL 管线（不计入考核）</p></a><a class="path-card" href="/guide/32-tsl-compute/basics"><h4>㉜ TSL 与 GPU 计算</h4><p><b class="path-stage path-stage--adv">前瞻</b>节点材质、compute shader、GPU 粒子场（不计入考核）</p></a><a class="path-card" href="/guide/33-cross-platform/basics"><h4>㉝ 跨端与框架广度</h4><p><b class="path-stage path-stage--adv">精通</b>Vue+TresJS、小程序适配、一套场景多端交付</p></a><a class="path-card" href="/guide/34-gis-mapping/basics"><h4>㉞ GIS 与地图深度融合</h4><p><b class="path-stage path-stage--adv">精通</b>坐标系与投影、瓦片与高程、城市级 GIS 场景</p></a><a class="path-card" href="/guide/35-scene-editor/basics"><h4>㉟ 场景编辑器</h4><p><b class="path-stage path-stage--adv">精通</b>gizmo 操控、撤销重做、序列化与迷你编辑器</p></a><a class="path-card" href="/guide/36-config-platform/basics"><h4>㊱ 配置化平台</h4><p><b class="path-stage path-stage--adv">精通</b>场景 DSL、校验与热更新、低代码配置台</p></a><a class="path-card" href="/guide/37-digital-human/basics"><h4>㊲ 数字人</h4><p><b class="path-stage path-stage--adv">精通</b>骨骼蒙皮、表情口型、可对话数字人</p></a><a class="path-card" href="/guide/38-gameplay-systems/basics"><h4>㊳ 游戏化与交互系统</h4><p><b class="path-stage path-stage--adv">精通</b>状态机、交互与任务、关卡与存档</p></a></div><h2 id="给不同读者的建议" tabindex="-1">给不同读者的建议 <a class="header-anchor" href="#给不同读者的建议" aria-label="Permalink to &quot;给不同读者的建议&quot;">​</a></h2><ul><li><strong>零基础读者</strong>：先完成 <a href="/threejs-tutorial-site/guide/00-prerequisites/">0 学前必备</a>的自查清单，确认 JavaScript 与运行环境两块硬性门槛过关，再严格按顺序学习，每个&quot;基础入门&quot;后的小练习务必亲手敲一遍，不要只复制粘贴。</li><li><strong>有其他 3D 引擎经验（Unity / Unreal）的读者</strong>：可快速浏览①–④建立 API 映射，重点阅读⑤–⑧中&quot;与传统引擎的差异&quot;部分。</li><li><strong>有一定 Three.js 基础的读者</strong>：建议从各模块的&quot;进阶应用&quot;切入，用&quot;实战案例&quot;检验掌握程度，遇到盲点再回跳基础篇。</li><li><strong>目标企业级场景的读者</strong>：完成 ①–⑪ 后，按&quot;精通方向扩展&quot;的阶段二～四继续推进，最终交付可定制特效、真实资产、工程化落地的行业级作品。</li></ul><h2 id="学习方法提示" tabindex="-1">学习方法提示 <a class="header-anchor" href="#学习方法提示" aria-label="Permalink to &quot;学习方法提示&quot;">​</a></h2><ol><li><strong>先跑起来再改</strong>：打开内嵌演示 → 点&quot;在线编辑&quot; → 每次只改一个参数，观察画面变化。</li><li><strong>用搜索建立索引</strong>：顶部搜索框支持全文检索，遇到具体问题（如&quot;阴影锯齿&quot;）直接搜关键词。</li><li><strong>善用 FAQ</strong>：每章末尾的常见问题覆盖了初学者 80% 的报错场景，卡住时先查它。</li><li><strong>画自己的管线图</strong>：每学完一个模块，尝试默写出它在渲染管线中的位置（本教程的 <a href="/threejs-tutorial-site/guide/01-intro/basics#three-js-的渲染管线">Diagram 示例</a>可作为起点）。</li></ol><p>准备好了吗？从 <a href="/threejs-tutorial-site/guide/01-intro/basics">1.1 基础入门：Three.js 是什么与第一个场景</a> 开始吧。</p>',19)])])}const n=s(p,[["render",r]]);export{o as __pageData,n as default};
